                    embd_inp.insert(embd_inp.end(), embd.begin(), embd.end());
                    n_past += embd.size();

                    embd.clear();
                    embd_is_sampled = false;

                    if (done) break;

                    // Index into `antiprompts` of a stop tag completed by THIS
