                    capture_capped = silence_count < silence_target;
                    if (params.print_energy || athena_mind_debug)
                        fprintf(stderr, "main: barge confirm closed after %d ms (%s; "
                                        "target %d ms silence, floor %d ms, ceiling %d ms, polls %d)\n",
                                elapsed_ms(),
                                capture_capped ? "CAPPED — he was still speaking"
                                               : "closed on silence",
                                confirm_ms, params.barge_min_capture_ms,
                                max_capture_ms, confirm_polls);
